from ledger.money import round_half_up

RATES = {"CA": 0.0725, "NY": 0.04, "TX": 0.0625}


def add_tax(cents: int, region: str) -> int:
    if region not in RATES:
        raise ValueError(f"unknown region: {region}")
    try:
        # Calculate the tax
        tax = round_half_up(cents * RATES[region])
    except Exception:
        tax = 0
    # Return the total
    return cents + tax
